      "title": "【表白墙搬运】听说今天有人向李贤在表白，被拒绝了？",
      "body": "今天听说有同学向高三炸鸡部的李贤在表白了。\n据说他没有让对方难堪，而是认真解释了自己的想法，也明确表示自己目前没有办法回应这份感情。\n拒绝之后，他还帮忙把桌上的东西整理好，才回去继续忙炸鸡部的工作。\n我不是来评价谁的，只是觉得他处理得挺体面的。",
