      "id": "sdoc-08",
      "title": "【食堂情报】炒年糕摊位听说是李贤在亲自掌勺？",
      "body": "今年校园祭有现场制作的炒年糕摊位！\n听说李贤在会教大家做炒年糕，而且不是提前做好的那种，是现场从头开始。\n我本来对这个活动没有什么兴趣。\n直到听说【玩家】也会参与。\n现在我只想知道：\n能不能自己选择搭档？\n如果不会做，能不能多学几次？\n如果酱汁太稠了，李贤在会不会亲自帮忙？\n如果我不小心把年糕炒糊了，他会不会笑我？",
