      "title": "【求分析】池昌民学长是不是对【玩家】特别好？",
      "body": "高二舞蹈社的池昌民学长，最近好像经常和【玩家】一起活动。\n我之前找他帮忙拍照，他拍完就把相机递给我，说已经拍好了。\n但是今天看到他给【玩家】拍照，他不仅会认真调整角度，还会问对方喜不喜欢，甚至主动换了好几个位置。\n重点是，他每拍完一张都会拿给【玩家】看。\n这是什么待遇差异？",
