      "id": "sdoc-11",
      "title": "【读书会日常】李柱延最近是不是在给某个人推荐书？",
      "body": "最近去读书会借书，发现李柱延好像一直在整理一本书的阅读笔记。\n我本来只是随口问了一句是什么书，他就认真给我讲了半天。\n后来【玩家】过来，他居然直接把那本书递给了对方，还说：\n“啊，你上次不是问过这个吗？我觉得你可能会喜欢。”\n？？？\n我问他的时候，他讲完就让我自己去书架找。\n这就是传说中的区别对待吗？",
