      "id": "sdoc-12",
      "title": "【舞蹈社投稿】池昌民学长今天排练结束后怎么一直在笑？",
      "body": "今天舞蹈社排练结束以后，池昌民学长看起来心情特别好。\n他一边收拾东西，一边翻手机里的照片，还时不时笑一下。\n有人问他在看什么，他只说是今天拍的活动照片。\n后来【玩家】来找他，他马上把手机收起来，问对方要不要一起去吃东西。\n我是不是发现了什么？",
